#!/usr/bin/env python3

"""Generate a large, single-call managed multi-DOALL benchmark."""

from pathlib import Path


ELEMENT_COUNT = 4_194_304
DOALL_COUNT = 8
MASK = 16_777_215
SAMPLE_INDICES = (0, ELEMENT_COUNT // 2, ELEMENT_COUNT - 1)


def apply_doall(value: int, original: int, doall_index: int) -> int:
    value ^= (90 + doall_index) & 0xFF
    value = (value + original) & 0xFFFFFFFF
    value = (value * 3) & 0xFFFFFFFF
    value //= (original & 7) + 1
    value = (value + doall_index + 1) & 0xFFFFFFFF
    return value & MASK


def result_for(value: int) -> int:
    original = value
    for doall_index in range(DOALL_COUNT):
        value = apply_doall(value, original, doall_index)
    return value


def emit_loop(source: str, destination: str, doall_index: int) -> list[str]:
    addend = doall_index + 1
    xor_value = (90 + doall_index) & 0xFF
    expression = (
        f"(((((({source} ^ {xor_value}) + input[i]) * 3) / "
        f"((input[i] & 7) + 1)) + {addend}) & {MASK})"
    )
    return (
        [
            "    for (i in 0..count) {",
            f"        {destination}[i] = {expression};",
            "    }",
        ]
    )


def emit_doalls(cpu: bool) -> str:
    lines: list[str] = []
    source = "input[i]"
    for doall_index in range(DOALL_COUNT):
        if doall_index == DOALL_COUNT - 1:
            destination = "output"
        elif doall_index % 2 == 0:
            destination = "tmp1"
        else:
            destination = "tmp2"
        lines.extend(emit_loop(source, destination, doall_index))
        lines.append("")
        source = f"{destination}[i]"
    return "\n".join(lines).rstrip()


def checks(buffer_name: str) -> str:
    return "\n".join(
        f"    if ({buffer_name}[{index}] != {result_for(index)}) {{ return 0; }}"
        for index in SAMPLE_INDICES
    )


def generate() -> str:
    cpu_doalls = emit_doalls(cpu=True)
    gpu_doalls = emit_doalls(cpu=False)
    return f"""// Generated by generate-multi-doall.py. Do not edit by hand.
// One call performs {DOALL_COUNT} ordered DOALL kernels over {ELEMENT_COUNT} elements.

var md_input = Packed.uint32({ELEMENT_COUNT});
var md_cpu_tmp1 = Packed.uint32({ELEMENT_COUNT});
var md_cpu_tmp2 = Packed.uint32({ELEMENT_COUNT});
var md_cpu_output = Packed.uint32({ELEMENT_COUNT});
var md_gpu_output = Packed.uint32({ELEMENT_COUNT});

func md_single_cpu(input: rpackeduint32,
                   tmp1: rpackeduint32,
                   tmp2: rpackeduint32,
                   output: rpackeduint32,
                   count: int): void {{
{cpu_doalls}
}}

__accel func md_single_gpu(input: rpackeduint32_in,
                           output: rpackeduint32_out,
                           count: int): void {{
    let tmp1 = Packed.uint32(count);
    let tmp2 = Packed.uint32(count);
{gpu_doalls}
}}

func md_setup(): void {{
    for (i in 0..{ELEMENT_COUNT}) {{
        md_input[i] = i;
    }}
}}

func md_cpu_run(): void {{
    md_single_cpu(md_input, md_cpu_tmp1, md_cpu_tmp2,
                  md_cpu_output, {ELEMENT_COUNT});
}}

func md_gpu_run(): void {{
    Accel.call(md_single_gpu, md_input, md_gpu_output, {ELEMENT_COUNT});
}}

func md_verify_cpu(): int {{
{checks("md_cpu_output")}
    return 1;
}}

func md_verify_gpu(): int {{
{checks("md_gpu_output")}
    return 1;
}}
"""


if __name__ == "__main__":
    destination = Path(__file__).with_name("multi-doall.noct")
    destination.write_text(generate(), encoding="utf-8")
